          style={styles.logo}
        />
        <Text font="Silkscreen-Regular" size={TextSize.medium}>
          CLOAK
        </Text>
      </Block>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  logo: {
    marginVertical: "auto",
  },
});

